// Read-only cloud provenance and an isolated backup/restore before source ingestion.
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { SQLiteBackupManager, validationCountsMatch } from '../lib/backup-manager.mjs';
const exec = promisify(execFile);
const postReuse = process.argv.includes('--post-reuse');
const backupOnly = postReuse || process.argv.includes('--backup-only');
const prefix = 'data/maintenance-journal/2026-09-28-source-catchup' + (postReuse ? '-post-reuse' : backupOnly ? '-final' : '');
const manager = new SQLiteBackupManager({ databasePath: 'data/douyin-monitor.sqlite', backupDir: 'data/backups/maintenance-20260928-source-catchup', retention: 60 });
const backup = await manager.createBackup('source-catchup');
if (backup.status !== 'created') throw new Error('Expected fresh snapshot');
const verified = await manager.verifySnapshot(backup.path);
const restored = await manager.restoreSnapshot(backup.path, join(mkdtempSync(join(tmpdir(), 'mcn-source-catchup-')), 'restored.sqlite'));
const recovery = { checkedAt: new Date().toISOString(), backupPath: backup.path, restoredPath: restored.path, sha256: verified.manifest.sha256, validation: verified.validation, recoveredValidation: restored.validation, countsMatch: validationCountsMatch(verified.validation.counts, restored.validation.counts), liveDatabaseOverwritten: false };
writeFileSync(prefix+'-restore.json', JSON.stringify(recovery,null,2)+'\n');
if (!recovery.countsMatch) throw new Error('Restore counts mismatch');
console.log(JSON.stringify({ backupPath: backup.path, sha256: recovery.sha256, countsMatch: true }));
if (backupOnly) process.exit(0);
const args = ['sheets', '+csv-get', '--spreadsheet-token', 'UbeEsThm3h1fsktWiEaclM1enOe', '--sheet-id', 'HyRxYp', '--range', 'A1:G52', '--rows-json', '--as', 'user', '--format', 'json'];
const {stdout} = await exec('lark-cli', args, { timeout: 60000, maxBuffer: 4*1024*1024, env: {...process.env, LARK_CLI_NO_PROXY:'1'} });
const envelope = JSON.parse(stdout), data = envelope.data;
if (!envelope.ok || data.has_more || data.data_not_fully_read || data.actual_range !== 'A1:G52' || data.revision !== 5320 || data.rows?.length !== 52) throw new Error('Incomplete or changing new-sheet read');
const payload = { readAt: new Date().toISOString(), purpose:'source-catalog-evidence-only-not-metric-import', sourceUrl:'https://tcnr35i27578.feishu.cn/sheets/UbeEsThm3h1fsktWiEaclM1enOe?sheet=HyRxYp', data };
writeFileSync(prefix+'-HyRxYp.json',JSON.stringify(payload,null,2)+'\n');
const rows = data.rows.slice(1), nonempty = rows.filter(r=>Object.values(r.values||{}).some(v=>String(v).trim()));
console.log(JSON.stringify({ readAt:payload.readAt, region:data.current_region, rows:rows.length, nonemptyRows:nonempty.length, uniqueIds:new Set(nonempty.map(r=>String(r.values.B||'').trim()).filter(Boolean)).size, hasMore:data.has_more, revision:data.revision }));
